// ─── CONFIG ───────────────────────────────────────────────────────
const OWNER_EMAIL_MAP = {
  'Deepti':  'deepti@swissbeauty.in',
  'Ayushi':  'ayushi@swissbeauty.in',
  'Shreya':  'shreya@swissbeauty.in',
  'Sharad':  'sharad@swissbeauty.in',
  'Afzal':   'afzal@swissbeauty.in',
  'Sheetal': 'sheetal@swissbeauty.in',
  'Milan':   'milan@swissbeauty.in',
  'Ananya':  'ananya@swissbeauty.in',
  'Vidushi': 'vidushi@swissbeauty.in',
  // add more owners here
};

const CC = ['sahil.gaur@swissbeauty.in', 'mohit@swissbeauty.in'];

// ─── HELPERS ──────────────────────────────────────────────────────
function buildHtml(owner, rows, reportDate) {
  const tableRows = rows.map(r => `
    <tr>
      <td class="td">${r['Product']}</td>
      <td class="td">${r['Brand']}</td>
      <td class="td">${r['Team']}</td>
      <td class="td">${r['Plan Date'] || '—'}</td>
      <td class="td">${r['Given Date']}</td>
      <td class="td" style="color:#c0392b;font-weight:bold">${r['Days Overdue']} days</td>
    </tr>`).join('');

  return `<!DOCTYPE html><html><head><style>
    body{font-family:Arial,sans-serif;color:#333;font-size:14px}
    h2{color:#1a1a2e}
    table{border-collapse:collapse;width:100%;margin-top:16px}
    th{background:#1a1a2e;color:#fff;padding:10px 12px;text-align:left;font-size:13px}
    .td{padding:8px 12px;border:1px solid #ddd;vertical-align:top}
    tr:nth-child(even) .td{background:#f9f9f9}
    .footer{margin-top:20px;font-size:12px;color:#aaa}
  </style></head><body>
  <h2>⚠️ Weekly TAT Overdue Report</h2>
  <p>Hi ${owner},</p>
  <p>The following items have <strong>passed their Given Date but are still not delivered</strong>.
  Action needed this week.</p>
  <p>Report: <strong>${reportDate}</strong> &nbsp;|&nbsp; Overdue items: <strong>${rows.length}</strong></p>
  <table>
    <thead><tr>
      <th>Product</th><th>Brand</th><th>Team</th>
      <th>Plan Date</th><th>Given Date</th><th>Days Overdue</th>
    </tr></thead>
    <tbody>${tableRows}</tbody>
  </table>
  <p class="footer">Automated weekly report · NPD/EPD Launch Tracker<br>
  Please update the sheet once delivered.</p>
  </body></html>`;
}

// ─── MAIN ─────────────────────────────────────────────────────────
const allRows = $input.all();

if (allRows.length === 0) {
  return [{ json: { _skip: true } }];
}

// First item might be empty if sheet has no data
const hasData = allRows.some(item => item.json['Product']);
if (!hasData) {
  return [{ json: { _skip: true } }];
}

// Group rows by owner
const byOwner = {};
for (const item of allRows) {
  const row = item.json;
  if (!row['Product']) continue;
  const owner = row['Owner'] || 'Unknown';
  if (!byOwner[owner]) byOwner[owner] = [];
  byOwner[owner].push(row);
}

const reportDate = allRows[0]?.json['Report Date'] || new Date().toLocaleDateString('en-GB', {day:'2-digit',month:'short',year:'numeric'});

return Object.entries(byOwner).map(([owner, rows]) => {
  const ownerEmail = OWNER_EMAIL_MAP[owner];
  const to = [...(ownerEmail ? [ownerEmail] : []), ...CC].join(', ');
  const count = rows.length;
  return {
    json: {
      _skip: false,
      to,
      subject: `⚠️ TAT Overdue Report – ${reportDate} · ${owner} has ${count} pending item${count !== 1 ? 's' : ''}`,
      html_body: buildHtml(owner, rows, reportDate),
      owner,
      count,
    }
  };
});
